import type { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";

export async function test_api_shoppingmall_order_item_deletion_by_admin(
  connection: api.IConnection,
) {
  // 1. Register admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        name: RandomGenerator.name(),
        password: "strongP@ssword123",
        phone_number: RandomGenerator.mobile(),
        role: "admin",
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin);

  // 2. Admin login to switch session
  await api.functional.auth.admin.login(connection, {
    body: {
      email: adminEmail,
      password: "strongP@ssword123",
      href: "https://test.admin.site/login",
      referrer: "https://test.admin.site",
    } satisfies IShoppingMallAdmin.ILogin,
  });

  // 3. Register customer
  const customerEmail: string = typia.random<string & tags.Format<"email">>();
  const customer: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: {
        email: customerEmail,
        password: "cust0merP@ss",
        full_name: RandomGenerator.name(),
        ip: "127.0.0.1",
        href: "https://test.customer.site/signup",
        referrer: "https://test.customer.site",
      } satisfies IShoppingMallCustomer.ICreate,
    });
  typia.assert(customer);

  // 4. Customer login to switch session
  await api.functional.auth.customer.login(connection, {
    body: {
      email: customerEmail,
      password: "cust0merP@ss",
      href: "https://test.customer.site/login",
      referrer: "https://test.customer.site",
    } satisfies IShoppingMallCustomer.ILogin,
  });

  // 5. Customer creates an order
  const orderNumber = RandomGenerator.alphaNumeric(10);
  const order: IShoppingMallOrder =
    await api.functional.shoppingMall.customer.shoppingMallOrders.create(
      connection,
      {
        body: {
          order_number: orderNumber,
          payment_status: "pending",
          status: "pending",
          total_amount: 999.99,
        } satisfies IShoppingMallOrder.ICreate,
      },
    );
  typia.assert(order);

  // 6. Customer adds an order item
  const productSkuId = typia.random<string & tags.Format<"uuid">>();
  const quantity = 1;
  const unitPrice = 999.99;
  const orderItem: IShoppingMallOrderItem =
    await api.functional.shoppingMall.customer.shoppingMallOrders.orderItems.createOrderItem(
      connection,
      {
        orderId: order.id,
        body: {
          product_sku_id: productSkuId,
          quantity: quantity,
          unit_price: unitPrice,
          status: "pending",
        } satisfies IShoppingMallOrderItem.ICreate,
      },
    );
  typia.assert(orderItem);

  // 7. Switch session to admin to delete order item
  await api.functional.auth.admin.login(connection, {
    body: {
      email: adminEmail,
      password: "strongP@ssword123",
      href: "https://test.admin.site/login",
      referrer: "https://test.admin.site",
    } satisfies IShoppingMallAdmin.ILogin,
  });

  // 8. Admin deletes the specific order item
  await api.functional.shoppingMall.admin.shoppingMallOrders.orderItems.erase(
    connection,
    {
      orderId: order.id,
      orderItemId: orderItem.id,
    },
  );

  // 9. After deletion, try to confirm the order item is deleted
  // This test environment lacks explicit GET APIs for items, so
  // we rely on error throwing on re-delete attempt
  await TestValidator.error(
    "deleting already deleted order item should fail",
    async () => {
      await api.functional.shoppingMall.admin.shoppingMallOrders.orderItems.erase(
        connection,
        {
          orderId: order.id,
          orderItemId: orderItem.id,
        },
      );
    },
  );

  // 10. Test unauthorized deletion attempt by customer
  await api.functional.auth.customer.login(connection, {
    body: {
      email: customerEmail,
      password: "cust0merP@ss",
      href: "https://test.customer.site/login",
      referrer: "https://test.customer.site",
    } satisfies IShoppingMallCustomer.ILogin,
  });

  await TestValidator.error(
    "customer should not delete order item",
    async () => {
      await api.functional.shoppingMall.admin.shoppingMallOrders.orderItems.erase(
        connection,
        {
          orderId: order.id,
          orderItemId: orderItem.id, // Even though it exists, customer lacks access
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";

/**
 * Test deletion of a specific order item within an order by the owning
 * customer.
 *
 * This test ensures that only the owning customer can delete items from their
 * order. It covers the scenario of customers registering, creating orders,
 * adding items, deleting one item, and verifying the consistency and
 * authorization checks.
 *
 * Steps:
 *
 * 1. Customer registers and authenticates.
 * 2. Customer creates a new order.
 * 3. Customer adds order items to the created order.
 * 4. Customer deletes one of the order items.
 * 5. Validate the deleted item is removed and order integrity is intact.
 * 6. Attempt deletion of an order item by a different customer and expect failure.
 */
export async function test_api_shoppingmall_order_item_deletion_by_customer(
  connection: api.IConnection,
) {
  // 1. Register and authenticate customer A
  const customerEmailA: string = typia.random<string & tags.Format<"email">>();
  const customerA: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: {
        email: customerEmailA,
        password: "1234",
        full_name: RandomGenerator.name(),
        ip: null,
        href: "https://example.com/signup",
        referrer: "https://example.com",
      } satisfies IShoppingMallCustomer.ICreate,
    });
  typia.assert(customerA);

  // 2. Customer A creates a new shopping mall order
  const orderCreateBody = {
    order_number: RandomGenerator.alphaNumeric(10),
    status: "pending",
    payment_status: "pending",
    total_amount: 1000,
  } satisfies IShoppingMallOrder.ICreate;

  const order: IShoppingMallOrder =
    await api.functional.shoppingMall.customer.shoppingMallOrders.create(
      connection,
      {
        body: orderCreateBody,
      },
    );
  typia.assert(order);

  // 3. Customer A adds two order items to the order
  const orderItemBody1 = {
    product_sku_id: typia.random<string & tags.Format<"uuid">>(),
    quantity: 1,
    unit_price: 600,
    status: "pending",
  } satisfies IShoppingMallOrderItem.ICreate;

  const orderItem1: IShoppingMallOrderItem =
    await api.functional.shoppingMall.customer.shoppingMallOrders.orderItems.createOrderItem(
      connection,
      {
        orderId: order.id,
        body: orderItemBody1,
      },
    );
  typia.assert(orderItem1);

  const orderItemBody2 = {
    product_sku_id: typia.random<string & tags.Format<"uuid">>(),
    quantity: 2,
    unit_price: 200,
    status: "pending",
  } satisfies IShoppingMallOrderItem.ICreate;

  const orderItem2: IShoppingMallOrderItem =
    await api.functional.shoppingMall.customer.shoppingMallOrders.orderItems.createOrderItem(
      connection,
      {
        orderId: order.id,
        body: orderItemBody2,
      },
    );
  typia.assert(orderItem2);

  // 4. Customer A deletes orderItem1
  await api.functional.shoppingMall.customer.shoppingMallOrders.orderItems.erase(
    connection,
    {
      orderId: order.id,
      orderItemId: orderItem1.id,
    },
  );

  // 5. Confirm orderItem1 is deleted by trying to delete again (expect error)
  await TestValidator.error(
    "deleting already deleted order item should fail",
    async () => {
      await api.functional.shoppingMall.customer.shoppingMallOrders.orderItems.erase(
        connection,
        {
          orderId: order.id,
          orderItemId: orderItem1.id,
        },
      );
    },
  );

  // 6. Register and authenticate customer B
  const customerEmailB: string = typia.random<string & tags.Format<"email">>();
  const customerB: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: {
        email: customerEmailB,
        password: "1234",
        full_name: RandomGenerator.name(),
        ip: null,
        href: "https://example.com/signup2",
        referrer: "https://example.com",
      } satisfies IShoppingMallCustomer.ICreate,
    });
  typia.assert(customerB);

  // 7. Attempt customer B deleting orderItem2 - should fail
  await TestValidator.error(
    "customer B cannot delete order item of customer A",
    async () => {
      await api.functional.shoppingMall.customer.shoppingMallOrders.orderItems.erase(
        connection,
        {
          orderId: order.id,
          orderItemId: orderItem2.id,
        },
      );
    },
  );

  // 8. Customer A deletes orderItem2
  await api.functional.shoppingMall.customer.shoppingMallOrders.orderItems.erase(
    connection,
    {
      orderId: order.id,
      orderItemId: orderItem2.id,
    },
  );

  // 9. Validate attempting to delete orderItem2 again fails
  await TestValidator.error("deleting a second time should fail", async () => {
    await api.functional.shoppingMall.customer.shoppingMallOrders.orderItems.erase(
      connection,
      {
        orderId: order.id,
        orderItemId: orderItem2.id,
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallChannelCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallChannelCategory";
import type { IShoppingMallChannelCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallChannelCategory";

export async function test_api_shopping_mall_channel_categories_filtered_list(
  connection: api.IConnection,
) {
  // Select a valid channelCode string (non-empty, allowed format) for tests
  const channelCode = "testChannel123";

  // Scenario 1: Default pagination without search or sort
  const defaultRequest = {
    page: 1,
    limit: 10,
  } satisfies IShoppingMallChannelCategory.IRequest;

  const defaultResponse =
    await api.functional.shoppingMall.shoppingMallChannels.shoppingMallChannelCategories.index(
      connection,
      { channelCode, body: defaultRequest },
    );
  typia.assert(defaultResponse);

  TestValidator.equals(
    "Default pagination: current page matches request",
    defaultResponse.pagination.current,
    defaultRequest.page,
  );
  TestValidator.equals(
    "Default pagination: limit matches request",
    defaultResponse.pagination.limit,
    defaultRequest.limit,
  );

  // If data present, pick substring from a code for search testing
  if (defaultResponse.data.length > 0) {
    const codeSearchTerm = defaultResponse.data[0].code.slice(0, 3);

    // Scenario 2: Search by partial code match
    const searchByCodeRequest = {
      search: codeSearchTerm,
      page: 1,
      limit: 5,
      orderBy: "code",
      orderDirection: "asc",
    } satisfies IShoppingMallChannelCategory.IRequest;

    const searchByCodeResponse =
      await api.functional.shoppingMall.shoppingMallChannels.shoppingMallChannelCategories.index(
        connection,
        { channelCode, body: searchByCodeRequest },
      );
    typia.assert(searchByCodeResponse);

    TestValidator.predicate(
      `Search by code '${codeSearchTerm}': all codes include search term`,
      searchByCodeResponse.data.every((v) => v.code.includes(codeSearchTerm)),
    );

    TestValidator.equals(
      "Search by code: current page matches request",
      searchByCodeResponse.pagination.current,
      searchByCodeRequest.page,
    );

    TestValidator.equals(
      "Search by code: limit matches request",
      searchByCodeResponse.pagination.limit,
      searchByCodeRequest.limit,
    );

    // Scenario 3: Search by partial name match
    const nameSearchTerm = defaultResponse.data[0].name.slice(0, 3);

    const searchByNameRequest = {
      search: nameSearchTerm,
      page: 1,
      limit: 5,
      orderBy: "name",
      orderDirection: "desc",
    } satisfies IShoppingMallChannelCategory.IRequest;

    const searchByNameResponse =
      await api.functional.shoppingMall.shoppingMallChannels.shoppingMallChannelCategories.index(
        connection,
        { channelCode, body: searchByNameRequest },
      );
    typia.assert(searchByNameResponse);

    TestValidator.predicate(
      `Search by name '${nameSearchTerm}': all names include search term`,
      searchByNameResponse.data.every((v) => v.name.includes(nameSearchTerm)),
    );

    TestValidator.equals(
      "Search by name: current page matches request",
      searchByNameResponse.pagination.current,
      searchByNameRequest.page,
    );

    TestValidator.equals(
      "Search by name: limit matches request",
      searchByNameResponse.pagination.limit,
      searchByNameRequest.limit,
    );

    // Scenario 4: Request a page beyond last page, expect empty data
    const beyondLastPageRequest = {
      page: searchByCodeResponse.pagination.pages + 1,
