    "coupon description",
    couponCreated.description,
    couponCreateBody.description,
  );
  TestValidator.equals(
    "discount type",
    couponCreated.discount_type,
    couponCreateBody.discount_type,
  );
  TestValidator.equals(
    "discount value",
    couponCreated.discount_value,
    couponCreateBody.discount_value,
