import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallChannel";
import type { IShoppingMallChannelCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallChannelCategory";

export async function test_api_shopping_mall_channel_category_deletion_by_admin(
  connection: api.IConnection,
) {
  // 1. Admin user registration and authorization
  const adminCreateBody = {
    email: `admin_${RandomGenerator.alphaNumeric(8)}@example.com`,
    name: RandomGenerator.name(),
    password: "Admin123!",
    phone_number: null,
    role: "admin",
  } satisfies IShoppingMallAdmin.ICreate;

  const adminAuthorized: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: adminCreateBody,
    });
  typia.assert(adminAuthorized);

  // 2. Create a shopping mall channel
  const channelCreateBody = {
    code: `chan_${RandomGenerator.alphaNumeric(6)}`,
    name: RandomGenerator.name(),
  } satisfies IShoppingMallChannel.ICreate;

  const channel: IShoppingMallChannel =
    await api.functional.shoppingMall.admin.shoppingMallChannels.create(
      connection,
      {
        body: channelCreateBody,
      },
    );
  typia.assert(channel);

  // 3. Create a shopping mall channel category under the created channel
  const channelCategoryCreateBody = {
    shopping_mall_product_category_id: typia.random<
      string & tags.Format<"uuid">
    >(),
    is_active: true,
    display_order: 1,
    notes: null,
  } satisfies IShoppingMallChannelCategory.ICreate;

  const channelCategory: IShoppingMallChannelCategory =
    await api.functional.shoppingMall.admin.shoppingMallChannels.shoppingMallChannelCategories.create(
      connection,
      {
        channelCode: channel.code,
        body: channelCategoryCreateBody,
      },
    );
  typia.assert(channelCategory);

  // 4. Delete the created channel category
  await api.functional.shoppingMall.admin.shoppingMallChannels.shoppingMallChannelCategories.erase(
    connection,
    {
      channelCode: channel.code,
      id: channelCategory.id,
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallConfiguration";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallConfiguration";

/**
 * Test the shopping mall configuration search endpoint as an authenticated
 * admin user.
 *
 * This e2e test covers:
 *
 * 1. Admin user registration and login via /auth/admin/join with valid data.
 * 2. Performing PATCH requests to /shoppingMall/admin/shoppingMallConfigurations
 *    to search configurations.
 * 3. Testing pagination functionality: page number, limit per page, and total
 *    records.
 * 4. Testing text-based searching with the 'search' query field.
 * 5. Testing sorting with 'sortBy' and 'sortDirection' fields.
 * 6. Validating response structure and type safety using typia.assert.
 * 7. Testing access control: only authorized admin users can perform search.
 * 8. Test multiple variants: no filters, keyword search, different sorting,
 *    different paging.
 *
 * Each API call's response is type-asserted. Pagination metadata is asserted
 * for consistency. Configuration summaries are checked to conform to expected
 * property types.
 *
 * This ensures the admin search functionality for mall configurations is robust
 * and correctly enforced.
 */
export async function test_api_shopping_mall_configuration_search_by_admin(
  connection: api.IConnection,
) {
  // 1. Register and authenticate a new admin user
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminCreateBody = {
    email: adminEmail,
    name: RandomGenerator.name(),
    password: "P@ssw0rd!123",
    phone_number: null,
    role: "admin",
  } satisfies IShoppingMallAdmin.ICreate;
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, { body: adminCreateBody });
  typia.assert(admin);

  // 2. Test default pagination without filters
  {
    const requestBody = {
      page: 1,
      limit: 10,
    } satisfies IShoppingMallConfiguration.IRequest;

    const response =
      await api.functional.shoppingMall.admin.shoppingMallConfigurations.index(
        connection,
        { body: requestBody },
      );
    typia.assert(response);

    TestValidator.predicate(
      "pagination current page and limit are positive",
      response.pagination.current >= 1 && response.pagination.limit >= 1,
    );
    TestValidator.predicate(
      "records count is non-negative and data length does not exceed limit",
      response.pagination.records >= 0 &&
        response.data.length <= response.pagination.limit,
    );
  }

  // 3. Test search keyword filter
  {
    const searchKeyword = "config";
    const requestBody = {
      page: 1,
      limit: 5,
      search: searchKeyword,
    } satisfies IShoppingMallConfiguration.IRequest;

    const response =
      await api.functional.shoppingMall.admin.shoppingMallConfigurations.index(
        connection,
        { body: requestBody },
      );
    typia.assert(response);

    // All returned keys or values should contain the search keyword string case-insensitive
    for (const item of response.data) {
      const keyContains = item.key
        .toLowerCase()
        .includes(searchKeyword.toLowerCase());
      const valueContains = item.value
        .toLowerCase()
        .includes(searchKeyword.toLowerCase());
      TestValidator.predicate(
        `item key or value contains keyword '${searchKeyword}'`,
        keyContains || valueContains,
      );
    }
  }

  // 4. Test sorting by key ascending and descending
  {
    const baseRequestBody = {
      page: 1,
      limit: 10,
      sortBy: "key",
    } satisfies IShoppingMallConfiguration.IRequest;

    // Ascending order
    const ascRequestBody = {
      ...baseRequestBody,
      sortDirection: "asc",
    } satisfies IShoppingMallConfiguration.IRequest;

    const ascResponse =
      await api.functional.shoppingMall.admin.shoppingMallConfigurations.index(
        connection,
        { body: ascRequestBody },
      );
    typia.assert(ascResponse);
    for (let i = 1; i < ascResponse.data.length; i++) {
      TestValidator.predicate(
        `item key ascending order at index ${i}`,
        ascResponse.data[i - 1].key <= ascResponse.data[i].key,
      );
    }

    // Descending order
    const descRequestBody = {
      ...baseRequestBody,
      sortDirection: "desc",
    } satisfies IShoppingMallConfiguration.IRequest;

    const descResponse =
      await api.functional.shoppingMall.admin.shoppingMallConfigurations.index(
        connection,
        { body: descRequestBody },
      );
    typia.assert(descResponse);
    for (let i = 1; i < descResponse.data.length; i++) {
      TestValidator.predicate(
        `item key descending order at index ${i}`,
        descResponse.data[i - 1].key >= descResponse.data[i].key,
      );
    }
  }

  // 5. Test pagination with high page number (likely to be empty results)
  {
    const requestBody = {
      page: 1000,
      limit: 10,
    } satisfies IShoppingMallConfiguration.IRequest;

    const response =
      await api.functional.shoppingMall.admin.shoppingMallConfigurations.index(
        connection,
        { body: requestBody },
      );
    typia.assert(response);

    TestValidator.equals(
      "high page number returns empty data",
      response.data.length,
      0,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCartItem";
import type { IShoppingMallCartItemSelectedOptions } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCartItemSelectedOptions";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import type { IShoppingMallShoppingCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShoppingCart";

export async function test_api_customer_shopping_cart_creation(
  connection: api.IConnection,
) {
  // 1. Seller joins (registers an account)
  const sellerEmail: string = typia.random<string & tags.Format<"email">>();
  const seller: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: sellerEmail,
        password: "1234",
        name: RandomGenerator.name(),
      } satisfies IShoppingMallSeller.ICreate,
    });
  typia.assert(seller);

  // 2. Seller logs in
  await api.functional.auth.seller.login(connection, {
    body: {
      email: sellerEmail,
      password: "1234",
      ip: null,
      href: "http://localhost/seller/login",
      referrer: "http://localhost/seller/referrer",
    } satisfies IShoppingMallSeller.ILogin,
  });

  // 3. Seller creates a shopping mall product
  const productCreateBody = {
    code: RandomGenerator.alphaNumeric(10),
    name: RandomGenerator.paragraph({ sentences: 3, wordMin: 5, wordMax: 10 }),
    description: RandomGenerator.content({
      paragraphs: 1,
      sentenceMin: 4,
      sentenceMax: 8,
      wordMin: 4,
      wordMax: 8,
    }),
    is_active: true,
  } satisfies IShoppingMallProduct.ICreate;

  const product: IShoppingMallProduct =
    await api.functional.shoppingMall.seller.shoppingMallProducts.create(
      connection,
      {
        body: productCreateBody,
      },
    );
  typia.assert(product);

  // 4. Customer joins (registers an account)
  const customerEmail: string = typia.random<string & tags.Format<"email">>();
  const customer: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: {
        email: customerEmail,
        password: "1234",
        full_name: RandomGenerator.name(),
        ip: null,
        href: "http://localhost/customer/join",
        referrer: "http://localhost/customer/referrer",
      } satisfies IShoppingMallCustomer.ICreate,
    });
  typia.assert(customer);

  // 5. Customer logs in
  await api.functional.auth.customer.login(connection, {
    body: {
      email: customerEmail,
      password: "1234",
      ip: null,
      href: "http://localhost/customer/login",
      referrer: "http://localhost/customer/referrer",
    } satisfies IShoppingMallCustomer.ILogin,
  });

  // 6. Customer creates a new shopping cart (initially empty)
  const cartCreateBody = {} satisfies IShoppingMallShoppingCart.ICreate;

  const shoppingCart: IShoppingMallShoppingCart =
    await api.functional.shoppingMall.customer.shoppingCarts.create(
      connection,
      {
        body: cartCreateBody,
      },
    );
  typia.assert(shoppingCart);

  // 7. Validate that the created shopping cart belongs to the customer
  TestValidator.equals(
    "shopping cart customer_id matches logged in customer id",
    shoppingCart.customer_id,
    customer.id,
  );

  // 8. Validate that the shopping cart id is a UUID (format checked by typia.assert)
  // Validate status is a string (e.g., "active" or other business value)
  TestValidator.predicate(
    "shopping cart id is a valid UUID",
    typeof shoppingCart.id === "string" && shoppingCart.id.length > 0,
  );
  TestValidator.predicate(
    "shopping cart status is a string",
    typeof shoppingCart.status === "string",
  );
  // 9. Validate created_at and updated_at are ISO date time strings
  TestValidator.predicate(
    "shopping cart created_at is a valid date-time string",
    typeof shoppingCart.created_at === "string" &&
      !isNaN(Date.parse(shoppingCart.created_at)),
  );
  TestValidator.predicate(
    "shopping cart updated_at is a valid date-time string",
    typeof shoppingCart.updated_at === "string" &&
      !isNaN(Date.parse(shoppingCart.updated_at)),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallArticleCategory";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";

export async function test_api_shopping_mall_article_category_update_by_customer(
  connection: api.IConnection,
) {
  // Authenticate admin (join + login)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AdminPass123!";
  const adminJoinBody = {
    email: adminEmail,
    name: RandomGenerator.name(),
    password: adminPassword,
    role: "admin",
  } satisfies IShoppingMallAdmin.ICreate;
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, { body: adminJoinBody });
  typia.assert(admin);

  await api.functional.auth.admin.login(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      href: "https://admin-login.example.com/",
      referrer: "https://admin-referrer.example.com/",
    } satisfies IShoppingMallAdmin.ILogin,
  });

  // Authenticate customer (join + login)
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "CustPass123!";
  const customerJoinBody = {
    email: customerEmail,
    password: customerPassword,
    full_name: RandomGenerator.name(),
    href: "https://customer-join.example.com/",
    referrer: "https://customer-referrer.example.com/",
  } satisfies IShoppingMallCustomer.ICreate;
  const customer: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: customerJoinBody,
    });
  typia.assert(customer);

  await api.functional.auth.customer.login(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      href: "https://customer-login.example.com/",
      referrer: "https://customer-referrer.example.com/",
    } satisfies IShoppingMallCustomer.ILogin,
  });

  // Admin creates initial shopping mall article category
  const initialCategoryCreateBody = {
    name: RandomGenerator.name(3),
    description: RandomGenerator.content({ paragraphs: 1 }),
    parent_id: null,
  } satisfies IShoppingMallArticleCategory.ICreate;
  const initialCategory: IShoppingMallArticleCategory =
    await api.functional.shoppingMall.admin.shoppingMallArticleCategories.create(
      connection,
      { body: initialCategoryCreateBody },
    );
  typia.assert(initialCategory);

  // Prepare update data for customer
  const updatedName = RandomGenerator.name(2);
  const updatedDescription = RandomGenerator.content({ paragraphs: 2 });

  // To update parent_id, create another category as parent
  const parentCategoryCreateBody = {
    name: RandomGenerator.name(2),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    parent_id: null,
  } satisfies IShoppingMallArticleCategory.ICreate;
  const parentCategory: IShoppingMallArticleCategory =
    await api.functional.shoppingMall.admin.shoppingMallArticleCategories.create(
      connection,
      { body: parentCategoryCreateBody },
    );
  typia.assert(parentCategory);

  // Customer updates the category
  const updateBody = {
    name: updatedName,
    description: updatedDescription,
    parent_id: parentCategory.id,
  } satisfies IShoppingMallArticleCategory.IUpdate;
  const updatedCategory: IShoppingMallArticleCategory =
    await api.functional.shoppingMall.customer.shoppingMallArticleCategories.update(
      connection,
      {
        shoppingMallArticleCategoryId: initialCategory.id,
        body: updateBody,
      },
    );
  typia.assert(updatedCategory);

  // Validate that the updated category response reflects the changes
  TestValidator.equals(
    "updated category id equals initial category id",
    updatedCategory.id,
    initialCategory.id,
  );
  TestValidator.equals(
    "updated category name matches",
    updatedCategory.name,
    updatedName,
  );
  TestValidator.equals(
    "updated category description matches",
    updatedCategory.description,
    updatedDescription,
  );
  TestValidator.equals(
    "updated category parent id matches new parent id",
    updatedCategory.parent_id,
    parentCategory.id,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallArticleCategory";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * This test validates the workflow of updating a shopping mall article category
 * by a seller.
 *
 * The business context: A seller must be authenticated to perform operations on
 * shopping mall entities. Therefore, the test begins by joining as a seller to
 * obtain authorization. Next, the seller creates an article category that
 * serves as the target for the update. Finally, the test updates the category's
 * name, description, and parent category. Validation asserts that the updates
 * are properly reflected in the API's response.
 *
 * This test ensures authentication, creation, modification, and validation
 * steps of article category management operate correctly and respect schema
 * constraints. It uses realistic random data generators and strict type safety
 * with typia.
 *
 * Steps:
 *
 * 1. Authenticate as a seller via join endpoint.
 * 2. Create a new article category as prerequisite data.
 * 3. Update the created article category with new data.
 * 4. Validate that the update response accurately reflects changes.
 *
 * All API calls are awaited, and responses are asserted for correct typing and
 * schema conformity. Null handling and optional fields follow explicit null
 * assignment policy to ensure accurate schema compliance.
 */
export async function test_api_shopping_mall_article_category_update_by_seller(
  connection: api.IConnection,
) {
  // 1. Seller join to authenticate.
  const sellerBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "1234",
    name: RandomGenerator.name(),
  } satisfies IShoppingMallSeller.ICreate;
  const seller: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, { body: sellerBody });
  typia.assert(seller);

  // 2. Prerequisite: create an article category as the seller.
  const categoryCreateBody = {
    name: RandomGenerator.paragraph({ sentences: 1, wordMin: 3, wordMax: 10 }),
    description: RandomGenerator.paragraph({
      sentences: 3,
      wordMin: 4,
      wordMax: 12,
    }),
    parent_id: null,
  } satisfies IShoppingMallArticleCategory.ICreate;

  const createdCategory: IShoppingMallArticleCategory =
    await api.functional.shoppingMall.seller.shoppingMallArticleCategories.create(
      connection,
      { body: categoryCreateBody },
    );
  typia.assert(createdCategory);

  // 3. Update the created category with new valid values.
  const updateBody = {
    name: RandomGenerator.paragraph({ sentences: 1, wordMin: 5, wordMax: 15 }),
    description: null, // Explicit null reset to remove description
    parent_id: null, // Explicit: keep as root category
  } satisfies IShoppingMallArticleCategory.IUpdate;

  const updatedCategory: IShoppingMallArticleCategory =
    await api.functional.shoppingMall.seller.shoppingMallArticleCategories.update(
      connection,
      {
        shoppingMallArticleCategoryId: createdCategory.id,
        body: updateBody,
      },
    );
  typia.assert(updatedCategory);

  // 4. Confirm that the updates have been applied correctly.
  TestValidator.equals(
    "updated category id",
    updatedCategory.id,
    createdCategory.id,
  );

  TestValidator.equals(
    "updated category name",
    updatedCategory.name,
    updateBody.name,
  );

  TestValidator.equals(
    "updated category description",
    updatedCategory.description,
    updateBody.description,
  );

  TestValidator.equals(
    "updated category parent id",
    updatedCategory.parent_id,
    updateBody.parent_id,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallArticleCategory";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Validate the creation of a shopping mall article category by a seller.
 *
 * This E2E test performs the following steps:
 *
 * 1. Seller signs up through the join endpoint to get authorized identity.
 * 2. Seller creates a top-level article category with a unique name and
 *    description.
 * 3. Verify the created category has all required properties and correct value
 *    types.
 * 4. Seller creates a sub-category with a parent_id referencing the previous
 *    category.
 * 5. Verify the sub-category's parent_id matches the parent's id and all other
 *    properties.
 */
export async function test_api_shopping_mall_seller_article_category_creation(
  connection: api.IConnection,
) {
  // 1. Seller signs up to get authorization
  const sellerCreate = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "TestPassword123!", // a valid password
    name: RandomGenerator.name(),
  } satisfies IShoppingMallSeller.ICreate;
  const seller: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, { body: sellerCreate });
  typia.assert(seller);

  // 2. Create a top-level article category without a parent
  const topCategoryCreate = {
    name: RandomGenerator.paragraph({
      sentences: 1,
      wordMin: 3,
      wordMax: 8,
    }).slice(0, 100),
    description: RandomGenerator.paragraph({
      sentences: 3,
      wordMin: 5,
      wordMax: 15,
    }),
    parent_id: null,
  } satisfies IShoppingMallArticleCategory.ICreate;
  const topCategory: IShoppingMallArticleCategory =
    await api.functional.shoppingMall.seller.shoppingMallArticleCategories.create(
      connection,
      { body: topCategoryCreate },
    );
  typia.assert(topCategory);
  TestValidator.predicate(
    "top-category id is uuid",
    /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(
      topCategory.id,
    ),
  );
  TestValidator.equals(
    "top-category name",
    topCategory.name,
    topCategoryCreate.name,
  );
  TestValidator.equals(
    "top-category description",
    topCategory.description,
    topCategoryCreate.description,
  );
  TestValidator.equals("top-category parent_id", topCategory.parent_id, null);
  TestValidator.predicate(
    "top-category created_at exists",
    topCategory.created_at !== null && topCategory.created_at !== undefined,
  );

  // 3. Create a sub-category with parent_id = topCategory.id
  const subCategoryCreate = {
    name: RandomGenerator.paragraph({
      sentences: 1,
      wordMin: 3,
      wordMax: 8,
    }).slice(0, 100),
    description: null,
    parent_id: topCategory.id,
  } satisfies IShoppingMallArticleCategory.ICreate;
  const subCategory: IShoppingMallArticleCategory =
    await api.functional.shoppingMall.seller.shoppingMallArticleCategories.create(
      connection,
      { body: subCategoryCreate },
    );
  typia.assert(subCategory);
  TestValidator.equals(
    "sub-category name",
    subCategory.name,
    subCategoryCreate.name,
  );
  TestValidator.equals(
    "sub-category description",
    subCategory.description,
    null,
  );
  TestValidator.equals(
    "sub-category parent_id",
    subCategory.parent_id,
    topCategory.id,
  );
  TestValidator.predicate(
    "sub-category created_at exists",
    subCategory.created_at !== null && subCategory.created_at !== undefined,
  );
}

