) {
  // 1. Customer joins and authenticates
  const customerCreateBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Password123!",
    full_name: RandomGenerator.name(),
    ip: null,
    href: "https://shoppingmall.example.com/register",
