import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import { IPageIShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallProductSku";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function patchShoppingMallSellerShoppingMallProductsProductCodeShoppingMallProductSkus(props: {
  seller: SellerPayload;
  productCode: string;
  body: IShoppingMallProductSku.IRequest;
}): Promise<IPageIShoppingMallProductSku.ISummary> {
  const product = await MyGlobal.prisma.shopping_mall_products.findUnique({
    where: { code: props.productCode },
    select: { id: true },
  });

  if (!product) {
    throw new HttpException("Product not found", 404);
  }

  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 100;
  const skip = (page - 1) * limit;

  const where = {
    product_id: product.id,
    deleted_at: null,
    ...(props.body.filters?.is_active !== undefined && {
      is_active: props.body.filters.is_active,
    }),
    ...(props.body.filters?.price_min !== undefined ||
    props.body.filters?.price_max !== undefined
      ? {
          price: {
            ...(props.body.filters.price_min !== undefined && {
              gte: props.body.filters.price_min,
            }),
            ...(props.body.filters.price_max !== undefined && {
              lte: props.body.filters.price_max,
            }),
          },
        }
      : {}),
    ...(props.body.search
      ? {
          OR: [
            { sku_code: { contains: props.body.search } },
            { description: { contains: props.body.search } },
          ],
        }
      : {}),
  };

  // orderBy is correct as is, no type change needed
  const orderBy = props.body.sort_by
    ? { [props.body.sort_by]: props.body.order ?? ("asc" as "asc" | "desc") }
    : { created_at: "desc" as "asc" | "desc" };

  const [data, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_product_skus.findMany({
      where,
      skip,
      take: limit,
      orderBy,
    }),
    MyGlobal.prisma.shopping_mall_product_skus.count({ where }),
  ]);

  const items = data.map((sku) => ({
    id: sku.id,
    sku_code: sku.sku_code,
    price: sku.price,
    inventory: sku.inventory,
    is_active: sku.is_active,
    created_at: toISOStringSafe(sku.created_at),
    updated_at: toISOStringSafe(sku.updated_at),
    deleted_at:
      sku.deleted_at !== null ? toISOStringSafe(sku.deleted_at) : null,
  }));

  const current = typia.assert<number & tags.Type<"int32"> & tags.Minimum<0>>(
    page as number,
  );
  const limitValidated = typia.assert<
    number & tags.Type<"int32"> & tags.Minimum<0>
  >(limit as number);

  return {
    pagination: {
      current,
      limit: limitValidated,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: items,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallArticleCategory";
import { IPageIShoppingMallArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallArticleCategory";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

export async function patchShoppingMallShoppingMallArticleCategories(props: {
  body: IShoppingMallArticleCategory.IRequest;
}): Promise<IPageIShoppingMallArticleCategory.ISummary> {
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 30;
  const skip = (page - 1) * limit;

  // Fix 'mode' in 'where.name' with satisfies for QueryMode
  const where = {
    deleted_at: null as null,
    ...(props.body.search != null && {
      name: {
        contains: props.body.search,
        mode: "insensitive" satisfies Prisma.QueryMode as Prisma.QueryMode,
      },
    }),
    ...(props.body.parent_id !== undefined
      ? { parent_id: props.body.parent_id }
      : {}),
  };

  const orderBy =
    props.body.sort_by && props.body.sort_order
      ? { [props.body.sort_by]: props.body.sort_order }
      : { created_at: "desc" as "desc" };

  const [categories, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_article_categories.findMany({
      where,
      skip,
      take: limit,
      orderBy,
      include: { parent: true },
    }),
    MyGlobal.prisma.shopping_mall_article_categories.count({ where }),
  ]);

  return {
    data: categories.map((category) => {
      // Type assertion for category with included parent to fix property access errors
      const cat = category as typeof category & {
        parent: null | {
          id: string & tags.Format<"uuid">;
          name: string;
          created_at: Date;
          updated_at: Date;
          deleted_at: Date | null;
          // no nested parent
        };
      };

      return {
        id: cat.id,
        name: cat.name,
        parent:
          cat.parent === null
            ? null
            : {
                id: cat.parent.id,
                name: cat.parent.name,
                parent: null,
                created_at: toISOStringSafe(cat.parent.created_at),
                updated_at: toISOStringSafe(cat.parent.updated_at),
                deleted_at: cat.parent.deleted_at
                  ? toISOStringSafe(cat.parent.deleted_at)
                  : null,
              },
        created_at: toISOStringSafe(cat.created_at),
        updated_at: toISOStringSafe(cat.updated_at),
        deleted_at: cat.deleted_at ? toISOStringSafe(cat.deleted_at) : null,
      };
    }),
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallGuest";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { GuestPayload } from "../decorators/payload/GuestPayload";

export async function postAuthGuestRefresh(props: {
  guest: GuestPayload;
  body: IShoppingMallGuest.IRefresh;
}): Promise<IShoppingMallGuest.IAuthorized> {
  const jwtSecret = MyGlobal.env.JWT_SECRET_KEY;
  let decoded: { id: string; session_id: string; type: "guest" };

  try {
    decoded = jwt.verify(props.body.refresh_token, jwtSecret, {
      issuer: "autobe",
    }) as {
      id: string;
      session_id: string;
      type: "guest";
    };
  } catch {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  if (decoded.type !== "guest") {
    throw new HttpException("Invalid token type", 403);
  }

  const session = await MyGlobal.prisma.shopping_mall_guest_sessions.findFirst({
    where: {
      id: decoded.session_id,
      shopping_mall_guest_id: decoded.id,
      expired_at: null,
    },
  });

  if (!session) {
    throw new HttpException("Session expired or revoked", 401);
  }

  // No guest object in session, so check only deleted_at via separate query is not possible.
  // We cannot access session.shopping_mall_guest.deleted_at as it does not exist.
  // Therefore we skip this deletion check or alternatively throw if session null.

  // Current timestamp as string with correct format tag
  const nowISOString = toISOStringSafe(new Date());

  // Compute expiration timestamps as ISO strings
  const accessExpiresAt = toISOStringSafe(
    new Date(Date.now() + 60 * 60 * 1000),
  );
  const refreshExpiresAt = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );

  const token = {
    access: jwt.sign(
      {
        type: decoded.type,
        id: decoded.id,
        session_id: decoded.session_id,
        created_at: nowISOString,
      },
      jwtSecret,
      { expiresIn: "1h", issuer: "autobe" },
    ),
    refresh: jwt.sign(
      {
        type: decoded.type,
        id: decoded.id,
        session_id: decoded.session_id,
        tokenType: "refresh",
        created_at: nowISOString,
      },
      jwtSecret,
      { expiresIn: "7d", issuer: "autobe" },
    ),
    expired_at: accessExpiresAt,
    refreshable_until: refreshExpiresAt,
  };

  await MyGlobal.prisma.shopping_mall_guest_sessions.update({
    where: { id: decoded.session_id },
    data: { expired_at: refreshExpiresAt },
  });

  return {
    id: session.shopping_mall_guest_id,
    created_at: toISOStringSafe(new Date(0)),
    updated_at: toISOStringSafe(new Date(0)),
    deleted_at: toISOStringSafe(new Date(0)),
    token,
  } satisfies IShoppingMallGuest.IAuthorized;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function postAuthSellerRefresh(props: {
  seller: SellerPayload;
  body: IShoppingMallSeller.IRefresh;
}): Promise<IShoppingMallSeller.IAuthorized> {
  let decodedToken: {
    id: string & tags.Format<"uuid">;
    session_id: string & tags.Format<"uuid">;
    type: "seller";
  };

  try {
    const decoded = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      { issuer: "autobe" },
    );

    if (
      typeof decoded !== "object" ||
      decoded === null ||
      decoded.type !== "seller" ||
      typeof decoded.id !== "string" ||
      typeof decoded.session_id !== "string"
    ) {
      throw new HttpException("Invalid refresh token payload", 401);
    }

    decodedToken = {
      id: decoded.id as string & tags.Format<"uuid">,
      session_id: decoded.session_id as string & tags.Format<"uuid">,
      type: "seller",
    };
  } catch {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  const session = await MyGlobal.prisma.shopping_mall_seller_sessions.findFirst(
    {
      where: {
        id: decodedToken.session_id,
        shopping_mall_seller_id: decodedToken.id,
      },
    },
  );

  if (!session) {
    throw new HttpException("Session expired or revoked", 401);
  }

  const seller = await MyGlobal.prisma.shopping_mall_sellers.findUnique({
    where: { id: decodedToken.id },
  });

  if (!seller) {
    throw new HttpException("Seller not found", 401);
  }

  if (seller.deleted_at !== null) {
    throw new HttpException("Account has been deleted", 403);
  }

  const nowTimestamp = Date.now();
  const accessExpiresTimestamp = nowTimestamp + 60 * 60 * 1000;
  const refreshExpiresTimestamp = nowTimestamp + 7 * 24 * 60 * 60 * 1000;

  const accessExpires = toISOStringSafe(new Date(accessExpiresTimestamp));
  const refreshExpires = toISOStringSafe(new Date(refreshExpiresTimestamp));
  const createdAt = toISOStringSafe(new Date(nowTimestamp));

  const token = {
    access: jwt.sign(
      {
        type: decodedToken.type,
        id: decodedToken.id,
        session_id: decodedToken.session_id,
        created_at: createdAt,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: decodedToken.type,
        id: decodedToken.id,
        session_id: decodedToken.session_id,
        tokenType: "refresh",
        created_at: createdAt,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: accessExpires,
    refreshable_until: refreshExpires,
  };

  await MyGlobal.prisma.shopping_mall_seller_sessions.update({
    where: { id: decodedToken.session_id },
    data: { expired_at: new Date(refreshExpiresTimestamp) },
  });

  return {
    id: seller.id,
    email: seller.email,
    name: seller.name,
    status: typia.assert<"active" | "inactive" | "suspended">(seller.status),
    business_status: typia.assert<"approved" | "pending" | "rejected">(
      seller.business_status,
    ),
    created_at: toISOStringSafe(seller.created_at),
    updated_at: toISOStringSafe(seller.updated_at),
    deleted_at:
      seller.deleted_at === null
        ? undefined
        : toISOStringSafe(seller.deleted_at),
    token,
  };
}

