import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallSkuAttribute } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSkuAttribute";
import { IPageIShoppingMallSkuAttribute } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallSkuAttribute";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

export async function patchShoppingMallShoppingMallSkuAttributes(props: {
  body: IShoppingMallSkuAttribute.IRequest;
}): Promise<IPageIShoppingMallSkuAttribute.ISummary> {
  const page =
    props.body.page && props.body.page > 0
      ? props.body.page
      : (1 satisfies number as number);
  const limit = (props.body.limit && props.body.limit > 0
    ? props.body.limit
    : 100) satisfies number as number;
  const skip = ((page - 1) * limit) satisfies number as number;

  const search = props.body.search?.trim() ?? undefined;

  const orderByField =
    props.body.orderBy && typeof props.body.orderBy === "string"
      ? props.body.orderBy
      : "code";
  const orderDirection = props.body.orderDirection === "desc" ? "desc" : "asc";

  // Build where clause with optional search filtering
  const where = search
    ? {
        OR: [
          {
            code: {
              contains: search,
              mode: "insensitive" as const,
            },
          },
          {
            name: {
              contains: search,
              mode: "insensitive" as const,
            },
          },
        ],
      }
    : undefined;

  const [data, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_sku_attributes.findMany({
      where,
      skip,
      take: limit,
      orderBy: { [orderByField]: orderDirection },
    }),
    MyGlobal.prisma.shopping_mall_sku_attributes.count({ where }),
  ]);

  return {
    pagination: {
      current: page satisfies number as number,
      limit: limit satisfies number as number,
      records: total,
      pages: Math.ceil(total / limit) satisfies number as number,
    },
    data: data.map((item) => ({
      id: item.id,
      code: item.code,
      name: item.name,
    })),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthAdminJoin(props: {
  body: IShoppingMallAdmin.ICreate;
}): Promise<IShoppingMallAdmin.IAuthorized> {
  // Check if the admin with the given email already exists
  const existingAdmin = await MyGlobal.prisma.shopping_mall_admins.findUnique({
    where: { email: props.body.email },
  });

  if (existingAdmin) {
    throw new HttpException("Email is already registered", 409);
  }

  // Hash the password securely
  const hashedPassword = await PasswordUtil.hash(props.body.password);

  // Prepare timestamp strings
  const now = toISOStringSafe(new Date());
  const accessExpires = toISOStringSafe(new Date(Date.now() + 60 * 60 * 1000));
  const refreshExpires = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );

  // Generate UUIDs for admin and session
  const adminId = v4();
  const sessionId = v4();

  // Create the new admin record
  const admin = await MyGlobal.prisma.shopping_mall_admins.create({
    data: {
      id: adminId as string & tags.Format<"uuid">,
      email: props.body.email,
      name: props.body.name,
      password_hash: hashedPassword,
      created_at: now,
      updated_at: now,
      deleted_at: null,
      business_status: "active",
      status: "enabled",
    },
  });

  // Create the new admin session record
  const session = await MyGlobal.prisma.shopping_mall_admin_sessions.create({
    data: {
      id: sessionId as string & tags.Format<"uuid">,
      shopping_mall_admin_id: adminId,
      created_at: now,
      expired_at: accessExpires,
      ip: "",
      href: "",
      referrer: "",
    },
  });

  // Generate JWT access and refresh tokens
  const nowStr = toISOStringSafe(new Date());
  const accessToken = jwt.sign(
    {
      type: "admin",
      id: admin.id,
      session_id: session.id,
      created_at: nowStr,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: "admin",
      id: admin.id,
      session_id: session.id,
      tokenType: "refresh",
      created_at: nowStr,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  // Compose the token response
  const token: IAuthorizationToken = {
    access: accessToken,
    refresh: refreshToken,
    expired_at: accessExpires,
    refreshable_until: refreshExpires,
  };

  // Return the authorized admin information
  return {
    id: admin.id,
    email: admin.email,
    name: admin.name,
    role: props.body.role,
    is_active: true,
    created_at: toISOStringSafe(admin.created_at),
    updated_at: toISOStringSafe(admin.updated_at),
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
