import { IShoppingMallSkuOption } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSkuOption";
import { IPageIShoppingMallSkuOption } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallSkuOption";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

export async function patchShoppingMallShoppingMallSkuOptions(props: {
  body: IShoppingMallSkuOption.IRequest;
}): Promise<IPageIShoppingMallSkuOption.ISummary> {
  const {
    page = 1,
    limit = 100,
    search,
    code,
    minPriceAdjustment,
    maxPriceAdjustment,
    sortBy,
    sortOrder = "asc",
    includeDeleted = false,
    exactMatch = false,
    categoryCode,
  } = props.body;

  const skip = (page - 1) * limit;

  const where = {
    ...(includeDeleted ? {} : { deleted_at: null }),
    ...(code ? { code: code } : {}),
    ...(minPriceAdjustment !== undefined
      ? { price_adjustment: { gte: minPriceAdjustment } }
      : {}),
    ...(maxPriceAdjustment !== undefined
      ? { price_adjustment: { lte: maxPriceAdjustment } }
      : {}),
    ...(search
      ? exactMatch
        ? { name: search }
        : { name: { contains: search } }
      : {}),
    ...(categoryCode ? { category_code: categoryCode } : {}),
  };

  const orderKey: string | undefined =
    sortBy === "createdAt"
      ? "created_at"
      : sortBy === "updatedAt"
        ? "updated_at"
        : sortBy === "priceAdjustment"
          ? "price_adjustment"
          : sortBy || undefined;

  const [data, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_sku_options.findMany({
      where,
      skip,
      take: limit,
      orderBy: orderKey
        ? {
            [orderKey]: sortOrder,
          }
        : undefined,
    }),
    MyGlobal.prisma.shopping_mall_sku_options.count({ where }),
  ]);

  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: data.map((item) => ({
      id: item.id,
      name: item.name,
      type: "summary",
    })),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function postAuthCustomerRefresh(props: {
  customer: CustomerPayload;
  body: IShoppingMallCustomer.IRefresh;
}): Promise<IShoppingMallCustomer.IAuthorized> {
  let decoded: {
    id: string & tags.Format<"uuid">;
    session_id: string & tags.Format<"uuid">;
    type: "customer";
  };
  try {
    decoded = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      { issuer: "autobe" },
    ) as {
      id: string & tags.Format<"uuid">;
      session_id: string & tags.Format<"uuid">;
      type: "customer";
    };
  } catch {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  if (decoded.type !== "customer") {
    throw new HttpException("Invalid token type", 403);
  }

  const session =
    await MyGlobal.prisma.shopping_mall_customer_sessions.findFirst({
      where: {
        id: decoded.session_id,
        shopping_mall_customer_id: decoded.id,
      },
      include: {
        customer: true,
      },
    });

  if (!session) {
    throw new HttpException("Session expired or revoked", 401);
  }

  if (session.customer.deleted_at !== null) {
    throw new HttpException("Account has been deleted", 403);
  }

  const nowIso = toISOStringSafe(new Date());
  const accessExpiresIso = toISOStringSafe(
    new Date(Date.now() + 60 * 60 * 1000),
  );
  const refreshExpiresIso = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );

  const access = jwt.sign(
    {
      type: decoded.type,
      id: decoded.id,
      session_id: decoded.session_id,
      created_at: nowIso,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "1h", issuer: "autobe" },
  );

  const refresh = jwt.sign(
    {
      type: decoded.type,
      id: decoded.id,
      session_id: decoded.session_id,
      tokenType: "refresh",
      created_at: nowIso,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "7d", issuer: "autobe" },
  );

  await MyGlobal.prisma.shopping_mall_customer_sessions.update({
    where: { id: decoded.session_id },
    data: { expired_at: refreshExpiresIso },
  });

  return {
    id: session.customer.id,
    email: session.customer.email,
    name: session.customer.name,
    status: typia.assert<"active" | "inactive" | "banned">(
      (session.customer as any).status ?? "active",
    ),
    created_at: toISOStringSafe(session.customer.created_at),
    updated_at: session.customer.updated_at
      ? toISOStringSafe(session.customer.updated_at)
      : null,
    token: {
      access: access,
      refresh: refresh,
      expired_at: accessExpiresIso,
      refreshable_until: refreshExpiresIso,
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function postAuthSellerJoin(props: {
  seller: SellerPayload;
  body: IShoppingMallSeller.ICreate;
}): Promise<IShoppingMallSeller.IAuthorized> {
  const existing = await MyGlobal.prisma.shopping_mall_sellers.findFirst({
    where: { email: props.body.email },
  });
  if (existing) {
    throw new HttpException("Email already registered", 409);
  }

  const hashedPassword = await PasswordUtil.hash(props.body.password);

  const nowISOString = toISOStringSafe(new Date());
  const newSellerId = v4();

  const seller = await MyGlobal.prisma.shopping_mall_sellers.create({
    data: {
      id: newSellerId,
      email: props.body.email,
      password_hash: hashedPassword,
      name: props.body.name,
      status: "active",
      business_status: "pending",
      created_at: nowISOString,
      updated_at: nowISOString,
    },
  });

  const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

  const accessExpiresISOString = toISOStringSafe(accessExpires);
  const refreshExpiresISOString = toISOStringSafe(refreshExpires);

  const session = await MyGlobal.prisma.shopping_mall_seller_sessions.create({
    data: {
      id: v4(),
      shopping_mall_seller_id: seller.id,
      created_at: nowISOString,
      expired_at: accessExpiresISOString,
      ip: "",
      href: "",
      referrer: "",
    },
  });

  const token = {
    access: jwt.sign(
      {
        type: "seller",
        id: seller.id,
        session_id: session.id,
        created_at: nowISOString,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
