      quantity: item.quantity,
      price_per_unit: item.unit_price,
      total_price: item.unit_price * item.quantity,
      status: item.status,
    };
  });

  // Assemble pagination info
  return {
    data,
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
