import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallChannelCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallChannelCategory";
import { IPageIShoppingMallChannelCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallChannelCategory";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

export async function patchShoppingMallShoppingMallChannelsChannelCodeShoppingMallChannelCategories(props: {
  channelCode: string;
  body: IShoppingMallChannelCategory.IRequest;
}): Promise<IPageIShoppingMallChannelCategory.ISummary> {
  const channel = await MyGlobal.prisma.shopping_mall_channels.findUnique({
    where: { code: props.channelCode },
  });

  if (!channel) {
    throw new HttpException("Shopping mall channel not found", 404);
  }

  const page = props.body.page >= 1 ? props.body.page : 1;
  const limit =
    props.body.limit >= 1 && props.body.limit <= 100 ? props.body.limit : 20;
  const skip = (page - 1) * limit;

  const where: Prisma.shopping_mall_channel_categoriesWhereInput = {
    shopping_mall_channel_id: channel.id,
    ...(props.body.search
      ? {
          shopping_mall_product_category: {
            OR: [
              { code: { contains: props.body.search } },
              { name: { contains: props.body.search } },
            ],
          },
        }
      : {}),
  };

  const orderByArray: Prisma.shopping_mall_channel_categoriesOrderByWithRelationInput[] =
    props.body.orderBy && props.body.orderDirection
      ? [
          {
            [props.body.orderBy === "code"
              ? "shopping_mall_product_category"
              : props.body.orderBy]: props.body.orderDirection as
              | "asc"
              | "desc",
          },
        ]
      : [{ created_at: "desc" as "desc" }];

  const [items, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_channel_categories.findMany({
      where,
      skip,
      take: limit,
      orderBy: orderByArray,
    }),
    MyGlobal.prisma.shopping_mall_channel_categories.count({ where }),
  ]);

  // Extract product category ids
  const productCategoryIds = Array.from(
    new Set(items.map((item) => item.shopping_mall_product_category_id)),
  );

  // Batch query product categories
  const productCategories =
    await MyGlobal.prisma.shopping_mall_product_categories.findMany({
      where: { id: { in: productCategoryIds } },
    });

  // Map product categories by id for quick access
  const productCategoryMap = new Map(
    productCategories.map((pc) => [pc.id, pc]),
  );

  return {
    pagination: {
      current: page satisfies number as number,
      limit: limit satisfies number as number,
      records: total satisfies number as number,
      pages: Math.ceil(total / limit) satisfies number as number,
    },
    data: items.map((item) => {
      const productCategory = productCategoryMap.get(
        item.shopping_mall_product_category_id,
      );
      return {
        id: item.id satisfies string as string,
        code: productCategory?.code ?? ("" satisfies string as string),
        name: productCategory?.name ?? ("" satisfies string as string),
        created_at: item.created_at
          ? toISOStringSafe(item.created_at)
          : undefined,
      };
    }),
  } satisfies IPageIShoppingMallChannelCategory.ISummary;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthCustomerJoin(props: {
  body: IShoppingMallCustomer.ICreate;
}): Promise<IShoppingMallCustomer.IAuthorized> {
  // 1. Check if email already registered and not soft deleted
  const existingCustomer =
    await MyGlobal.prisma.shopping_mall_customers.findFirst({
      where: {
        email: props.body.email,
        deleted_at: null,
      },
    });

  if (existingCustomer) {
    throw new HttpException("Email already registered", 409);
  }

  // 2. Hash password
  const hashedPassword = await PasswordUtil.hash(props.body.password);

  // 3. Create customer actor record
  const now = new Date();
  const nowIso = toISOStringSafe(now);
  const customerId = v4();

  const dataToCreate = {
    id: customerId,
    email: props.body.email,
    password_hash: hashedPassword,
    name: props.body.full_name, // changed full_name to name per Prisma field
    status: "active",
    phone_number: null,
    created_at: nowIso,
    updated_at: nowIso,
    deleted_at: null,
  };

  // 3. Create shopping_mall_customer record
  const created = await MyGlobal.prisma.shopping_mall_customers.create({
    data: dataToCreate,
  });

  // 4. Create customer session record
  const accessExpireDate = new Date(Date.now() + 3600000);
  const refreshExpireDate = new Date(Date.now() + 604800000);
  const accessExpires = toISOStringSafe(accessExpireDate);
  const refreshExpires = toISOStringSafe(refreshExpireDate);

  const sessionId = v4();

  // ip must not be null, so if null or undefined, use empty string
  const ipAddress: string = props.body.ip ?? "";

  const session = await MyGlobal.prisma.shopping_mall_customer_sessions.create({
    data: {
      id: sessionId,
      shopping_mall_customer_id: customerId,
      ip: ipAddress,
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: nowIso,
      expired_at: accessExpires,
    },
  });

  // 5. Generate JWT tokens
  const token = {
    access: jwt.sign(
      {
        type: "customer",
        id: created.id,
        session_id: session.id,
        created_at: nowIso,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "customer",
        id: created.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: nowIso,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: accessExpires,
    refreshable_until: refreshExpires,
  };

  // 6. Return result
  return {
    id: created.id,
    email: created.email,
    name: dataToCreate.name,
    phone_number: null,
    status: dataToCreate.status,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthCustomerLogin(props: {
  body: IShoppingMallCustomer.ILogin;
}): Promise<IShoppingMallCustomer.IAuthorized> {
  const customer = await MyGlobal.prisma.shopping_mall_customers.findFirst({
    where: { email: props.body.email },
  });
  if (!customer) {
    throw new HttpException("Invalid credentials", 401);
  }

  const isValid = await PasswordUtil.verify(
    props.body.password,
    customer.password_hash,
  );
  if (!isValid) {
    throw new HttpException("Invalid credentials", 401);
  }

  const nowTimestamp = Date.now();
  const accessExpiresTimestamp = nowTimestamp + 60 * 60 * 1000; // 1 hour
  const refreshExpiresTimestamp = nowTimestamp + 7 * 24 * 60 * 60 * 1000; // 7 days

  const nowIso = toISOStringSafe(new Date(nowTimestamp));
  const accessExpires = toISOStringSafe(new Date(accessExpiresTimestamp));
  const refreshExpires = toISOStringSafe(new Date(refreshExpiresTimestamp));

  const session = await MyGlobal.prisma.shopping_mall_customer_sessions.create({
    data: {
      id: v4(),
      shopping_mall_customer_id: customer.id,
      ip: (props.body.ip ?? "") satisfies string as string,
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: nowIso,
      expired_at: accessExpires,
    },
  });

  const token = {
    access: jwt.sign(
      {
        type: "customer",
        id: customer.id,
        session_id: session.id,
        created_at: nowIso,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "1h", issuer: "autobe" },
    ),
    refresh: jwt.sign(
      {
        type: "customer",
        id: customer.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: nowIso,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "7d", issuer: "autobe" },
    ),
    expired_at: accessExpires,
    refreshable_until: refreshExpires,
  };

  return {
    id: customer.id,
    email: customer.email,
    name: customer.name,
    status: "active",
    created_at: toISOStringSafe(customer.created_at),
    updated_at:
      customer.updated_at !== null && customer.updated_at !== undefined
        ? toISOStringSafe(customer.updated_at)
        : null,
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function postAuthSellerLogin(props: {
  seller: SellerPayload;
  body: IShoppingMallSeller.ILogin;
}): Promise<IShoppingMallSeller.IAuthorized> {
  const seller = await MyGlobal.prisma.shopping_mall_sellers.findFirst({
    where: { email: props.body.email },
  });

  if (!seller) {
    throw new HttpException("Invalid credentials", 401);
  }

  if (seller.status !== "active" || seller.business_status !== "approved") {
    throw new HttpException("Account inactive or unapproved", 403);
  }

  const isPasswordValid = await PasswordUtil.verify(
    props.body.password,
    seller.password_hash,
  );
  if (!isPasswordValid) {
    throw new HttpException("Invalid credentials", 401);
  }

  const sessionId: string & tags.Format<"uuid"> = v4();

  const nowISO: string & tags.Format<"date-time"> = toISOStringSafe(new Date());
  const accessExpireISO: string & tags.Format<"date-time"> = toISOStringSafe(
    new Date(Date.now() + 60 * 60 * 1000),
  );
  const refreshExpireISO: string & tags.Format<"date-time"> = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );

  const session = await MyGlobal.prisma.shopping_mall_seller_sessions.create({
    data: {
      id: sessionId,
      shopping_mall_seller_id: seller.id,
      ip: (props.body.ip ?? "") satisfies string as string,
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: nowISO,
      expired_at: accessExpireISO,
    },
  });

  const accessToken = jwt.sign(
    {
      type: "seller",
      id: seller.id,
      session_id: session.id,
      created_at: nowISO,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: "seller",
      id: seller.id,
      session_id: session.id,
      tokenType: "refresh",
      created_at: nowISO,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  return {
    id: seller.id,
    email: seller.email,
    name: seller.name,
    status: seller.status,
    business_status: seller.business_status,
    created_at: toISOStringSafe(seller.created_at),
    updated_at: toISOStringSafe(seller.updated_at),
    deleted_at:
      seller.deleted_at === undefined
        ? undefined
        : seller.deleted_at === null
          ? null
          : toISOStringSafe(seller.deleted_at),
    token: {
      access: accessToken,
      refresh: refreshToken,
      expired_at: accessExpireISO,
      refreshable_until: refreshExpireISO,
    },
  };
}

