import { IShoppingMallArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallArticleCategory";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function postShoppingMallAdminShoppingMallArticleCategories(props: {
  admin: AdminPayload;
  body: IShoppingMallArticleCategory.ICreate;
}): Promise<IShoppingMallArticleCategory> {
  try {
    const now = toISOStringSafe(new Date()) as string &
      tags.Format<"date-time">;

    const data = {
      id: v4() as string & tags.Format<"uuid">,
      name: props.body.name,
      description: props.body.description ?? null,
      parent_id: props.body.parent_id ?? null,
      created_at: now,
      updated_at: now,
    };

    const created =
      await MyGlobal.prisma.shopping_mall_article_categories.create({
        data,
      });

    return {
      id: created.id,
      name: created.name,
      description: created.description ?? null,
      parent_id: created.parent_id ?? null,
      created_at: toISOStringSafe(created.created_at),
      updated_at:
        created.updated_at !== null && created.updated_at !== undefined
          ? toISOStringSafe(created.updated_at)
          : null,
    };
  } catch (error) {
    if (error instanceof Prisma.PrismaClientKnownRequestError) {
      if (
        error.code === "P2002" &&
        Array.isArray(error.meta?.target) &&
        error.meta.target.includes("name")
      ) {
        throw new HttpException("Article category name already exists", 400);
      }
    }
    throw error;
  }
}

