    status: cancellation.status,
    created_at: toISOStringSafe(cancellation.created_at),
    updated_at: toISOStringSafe(cancellation.updated_at),
    deleted_at: cancellation.deleted_at
      ? toISOStringSafe(cancellation.deleted_at)
